import{_ as o,o as e,c as r,a2 as s}from"./chunks/framework.DA69LXMH.js";const u=JSON.parse('{"title":"Voz & Transcrição (STT / TTS)","description":"","frontmatter":{},"headers":[],"relativePath":"recursos/voz-e-stt.md","filePath":"recursos/voz-e-stt.md"}'),t={name:"recursos/voz-e-stt.md"};function i(d,a,n,c,l,p){return e(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="voz-transcricao-stt-tts" tabindex="-1">Voz &amp; Transcrição (STT / TTS) <a class="header-anchor" href="#voz-transcricao-stt-tts" aria-label="Permalink to &quot;Voz &amp; Transcrição (STT / TTS)&quot;">​</a></h1><p>O coração do <strong>EchoBot</strong> é o seu motor avançado de processamento de áudio e voz em tempo real.</p><hr><h2 id="🎧-transcricao-de-fala-para-texto-stt" tabindex="-1">🎧 Transcrição de Fala para Texto (STT) <a class="header-anchor" href="#🎧-transcricao-de-fala-para-texto-stt" aria-label="Permalink to &quot;🎧 Transcrição de Fala para Texto (STT)&quot;">​</a></h2><p>O EchoBot utiliza modelos otimizados baseados no Whisper e Moonshine para transformar o áudio da sua mesa em texto indexado:</p><ul><li><strong>Detecção Automática de Fala (VAD):</strong> O sistema detecta pausas naturais na fala sem cortar o final das frases.</li><li><strong>Múltiplos Idiomas:</strong> Suporte com alta precisão para Português (PT-BR), Inglês e termos específicos de RPG (nomes de monstros, magias e regras).</li><li><strong>Processamento Local Privado:</strong> Nenhuma gravação de áudio precisa sair do seu computador para servidores de terceiros.</li></ul><hr><h2 id="🗣️-sintese-de-voz-tts-para-npcs-e-narrador" tabindex="-1">🗣️ Síntese de Voz (TTS) para NPCs e Narrador <a class="header-anchor" href="#🗣️-sintese-de-voz-tts-para-npcs-e-narrador" aria-label="Permalink to &quot;🗣️ Síntese de Voz (TTS) para NPCs e Narrador&quot;">​</a></h2><p>Dê vida aos NPCs da sua campanha com vozes personalizadas:</p><ol><li><strong>Edge TTS &amp; Lobe TTS:</strong> Vozes naturais e expressivas com controle de pitch, velocidade e tom dramático.</li><li><strong>Perfis de Voz por Personagem:</strong> Associe um estilo de voz único a cada taverneiro, vilão, criatura ou divindade da sua campanha.</li><li><strong>Reprodução Direta em Canal de Áudio:</strong> O áudio gerado pode ser transmitido diretamente para o Discord ou sala de voz dos jogadores.</li></ol>',10)])])}const T=o(t,[["render",i]]);export{u as __pageData,T as default};
